import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    op_d = 0
    my_d = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            op_c += 1
        else:
            op_d += 1
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    # Endgame: last few rounds defect against anyone not clearly punishing us.
    if n >= 97:
        # If opponent has been mostly cooperative and rarely punished, exploit.
        recent_punish = 0
        for i in range(max(0, n - 6), n):
            if op[i] == 'D' and me[i] == 'D':
                recent_punish += 1
        if op_c >= n - max(2, n // 20) and recent_punish == 0:
            return 'D'
        if n == 99:
            return 'D'
        if op[-1] == 'C':
            if rng.random() < 0.75:
                return 'D'
        return 'C'

    # Reputation-building early phase: cooperate initially, small probes.
    if n < 4:
        if n == 0:
            return 'C'
        if n == 1:
            if op[0] == 'D':
                return 'D'
            return 'C'
        if op[-1] == 'D' and op[-2] == 'D':
            return 'D'
        if op[-1] == 'D':
            return 'D'
        return 'C'

    # Detect almost-unconditional cooperator and exploit mildly.
    if op_d == 0:
        # Pure cooperator so far. Exploit occasionally but not too early to invite tests.
        if n >= 8:
            # Sparse exploitation: every ~5-7 rounds defect.
            if n >= 60:
                if rng.random() < 0.6:
                    return 'D'
                return 'C'
            if n >= 20:
                if rng.random() < 0.18:
                    return 'D'
                return 'C'
        return 'C'

    # Detect hard defector.
    if op_c == 0:
        return 'D'

    # Recent window stats.
    w = 10 if n >= 10 else n
    recent_op_d = 0
    recent_op_c = 0
    recent_me_d = 0
    recent_me_c = 0
    for i in range(n - w, n):
        if op[i] == 'D':
            recent_op_d += 1
        else:
            recent_op_c += 1
        if me[i] == 'D':
            recent_me_d += 1
        else:
            recent_me_c += 1

    # If we are trapped in mutual defection, try to escape with a cooperative probe.
    if recent_op_d >= w - 1:
        # Opponent is defecting almost always.
        if my_d >= 3 and op[-1] == 'D' and me[-1] == 'D':
            # Sparse escape attempts.
            if rng.random() < 0.08:
                return 'C'
        return 'D'

    if recent_op_d >= 2 and recent_op_c == 0:
        return 'D'

    # Count reciprocity: when we defected, did opponent retaliate?
    exploit_ok = 0
    exploit_fail = 0
    for i in range(1, n):
        if me[i - 1] == 'D' and op[i - 1] == 'C':
            if op[i] == 'D':
                exploit_fail += 1
            else:
                exploit_ok += 1

    last_me = me[-1]
    last_op = op[-1]

    # If opponent punished our defections reliably, cooperate to keep peace.
    if exploit_fail >= 3 and exploit_ok == 0:
        if last_op == 'D' and last_me == 'D':
            return 'C'
        if last_op == 'D':
            return 'C' if rng.random() < 0.8 else 'D'
        return 'C'

    # If exploiting was safe, do it modestly.
    if exploit_ok >= 3 and exploit_fail == 0:
        if n < 90:
            if last_op == 'C':
                if rng.random() < 0.35:
                    return 'D'
                return 'C'
        else:
            return 'D'

    # Main reciprocal core: respond to last opponent action with forgiveness.
    if last_op == 'D':
        # Forgive if opponent cooperated mostly in recent window.
        if recent_op_c >= (w * 3) // 4:
            if rng.random() < 0.35:
                return 'C'
        # If mutual defection too long, break out sometimes.
        if last_me == 'D' and recent_me_d >= 4:
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    # Opponent cooperated last.
    # If we have a long history of defecting against a cooperator, keep milking gently.
    if op_c > op_d * 4 and n > 15:
        if rng.random() < 0.12:
            return 'D'
    return 'C'
